#!/bin/sh
# PostToolUse hook of the plan-relay plugin: warns the session when its context gets near
# the limit, so that it hands off the baton instead of going on degraded.
# Runs after every tool, in every project. Exits at once, without reading the stdin or the
# transcript, when CLAUDE_PROJECT_DIR is set and has no agent_plans/; without the variable,
# when the cwd that the hook receives has none either.
# Reads the size of the last request to the model (input + cache) from the Claude Code
# transcript (the lines with message.usage; another agent will have another format).
# Warns once at 90 % of the limit and then every 50k above it.
# Limit: PLAN_RELAY_CONTEXT_LIMIT (tokens), else 150000, which fits a 200k window. Neither
# stdin nor the transcript tells the window size; whoever uses a 1M one sets the variable.
# Marks in <data>/context-<session>-<level>, and context-<session>-<agent>-<level> in a
# subagent, with <level> near or over-<n>; <data> is --data <dir>, else CLAUDE_PLUGIN_DATA
# (the hook gets it in its environment), else the default folder
# ${XDG_STATE_HOME:-~/.local/state}/plan-relay/ (the same as window.sh's, for an agent that
# does not inject the variable). When it writes a mark, it deletes the context-* ones older
# than 7 days, and the state files of older releases of that age too.
# The stdin JSON and the usage are read with jq; without jq, or if it fails, with sed and grep.
# The session id is cut to A-Za-z0-9_- before it names a mark.
# The warning comes out in the package language, with the name of the run skill's section in
# that language.

language='en'
# >>> strings (area contextHook.): generated by tools/script-strings.sh from agents/claude-code/i18n/*.json; do not edit by hand
case "$language" in
  [Xx]-[Tt][Ee][Ss][Tt]) msg_language="x-test" ;;
  [Pp][Tt]-[Bb][Rr]) msg_language="pt-BR" ;;
  [Pp][Tt]|[Pp][Tt]-*) msg_language="pt-BR" ;;
  *) msg_language="en" ;;
esac
# shellcheck disable=SC2016,SC2089 # backticks and quotes in the strings are text, not expansion
case "$msg_language" in
  x-test) MSG_TABLE='contextHook.near	x-test:contextHook.near {0} {1}
contextHook.over	x-test:contextHook.over {0} {1}
' ;;
  pt-BR) MSG_TABLE='contextHook.near	Contexto em {0}k tokens, perto do limite de {1}k. Feche o passo em curso sem abrir outro grande.
contextHook.over	Contexto em {0}k tokens, acima do limite de {1}k. Passe o bastão agora: termine o passo em curso, registre o «Next step:» e siga /plan-relay:handoff. Trabalhador do /plan-relay:run: devolva RESULT: INTERRUPTED. Condutora: siga a seção «Bastão» da skill.
' ;;
  *) MSG_TABLE='contextHook.near	Context at {0}k tokens, near the {1}k limit. Finish the current step without starting another big one.
contextHook.over	Context at {0}k tokens, above the {1}k limit. Hand off the baton now: finish the current step, record the Next step: line and follow /plan-relay:handoff. /plan-relay:run worker: return RESULT: INTERRUPTED. Conductor: follow the Baton section of the skill.
' ;;
esac
# shellcheck disable=SC2090 # a table read by awk from the environment, never split by the shell
export MSG_TABLE
MSG_AWK='
function msg_load(   m, ls, j, p) {
  msg_ok = 1
  m = split(ENVIRON["MSG_TABLE"], ls, "\n")
  for (j = 1; j <= m; j++) { p = index(ls[j], "\t"); if (p > 0) MSG[substr(ls[j], 1, p - 1)] = substr(ls[j], p + 1) }
}
function msg(k, a0, a1, a2, a3, a4, a5,   s, r, i, c) {
  if (!msg_ok) msg_load()
  s = (k in MSG) ? MSG[k] : k
  r = ""
  while ((i = index(s, "{")) > 0) {
    c = substr(s, i + 1, 2)
    if (c ~ /^[0-5][}]$/) {
      c = substr(c, 1, 1)
      r = r substr(s, 1, i - 1) (c == "0" ? a0 : (c == "1" ? a1 : (c == "2" ? a2 : (c == "3" ? a3 : (c == "4" ? a4 : a5)))))
      s = substr(s, i + 3)
    } else { r = r substr(s, 1, i); s = substr(s, i + 1) }
  }
  return r s
}
'
msg() { awk "$MSG_AWK"' BEGIN { print msg(ARGV[1], ARGV[2], ARGV[3], ARGV[4], ARGV[5], ARGV[6], ARGV[7]); exit }' "$@"; }
# <<< strings

data=
[ "$1" = --data ] && [ -n "$2" ] && data=$2

# CLAUDE_PROJECT_DIR, when the agent sets it, is the project the session belongs to: without
# agent_plans/ there, the hook leaves before reading the stdin. Without the variable, the cwd
# in the stdin decides, below.
[ -z "${CLAUDE_PROJECT_DIR-}" ] || [ -d "$CLAUDE_PROJECT_DIR/agent_plans" ] || exit 0

input=$(cat)
[ -n "$input" ] || exit 0

cwd=''; session=''; agent=''; transcript=''; agent_id=''
fields=''
if command -v jq >/dev/null 2>&1; then
  fields=$(printf '%s' "$input" | jq -r '.cwd // "", .session_id // "", .agent_transcript_path // "", .transcript_path // "", .agent_id // ""' 2>/dev/null) || fields=
fi
if [ -n "$fields" ]; then
  { read -r cwd; read -r session; read -r agent; read -r transcript; read -r agent_id; } <<EOF
$fields
EOF
else
  # On a single line, so that sed finds the key in any position. A key inside a string
  # (\"cwd\") does not match, because its double quotes come escaped.
  line=$(printf '%s' "$input" | tr '\n\r' '  ')
  field() { printf '%s' "$line" | sed -n "s/.*\"$1\" *: *\"\\([^\"]*\\)\".*/\\1/p"; }
  cwd=$(field cwd)
fi

has_plan() { [ -n "$1" ] && [ -d "$1/agent_plans" ]; }
has_plan "$CLAUDE_PROJECT_DIR" || has_plan "$cwd" || exit 0

if [ -z "$fields" ]; then
  session=$(field session_id)
  agent=$(field agent_transcript_path)
  transcript=$(field transcript_path)
  agent_id=$(field agent_id)
fi
# A subagent has the conductor's session_id: its mark gets a key of its own (agent_id, else
# the name of its transcript), so that the warning of one does not silence the other's. The
# conductor keeps context-<session>-<level>.
# The hooks documentation guarantees agent_id in a subagent's PostToolUse, but
# agent_transcript_path only in SubagentStop; without it, the subagent's transcript is
# <transcript without .jsonl>/subagents/agent-<agent_id>.jsonl.
agent_id=$(printf '%s' "$agent_id" | tr -cd 'A-Za-z0-9_-')
if [ -z "$agent" ] && [ -n "$agent_id" ] && [ -f "${transcript%.jsonl}/subagents/agent-$agent_id.jsonl" ]; then
  agent=${transcript%.jsonl}/subagents/agent-$agent_id.jsonl
fi
key=$agent_id
if [ -n "$agent" ]; then
  transcript=$agent
  [ -n "$key" ] || key=$(basename "$agent" .jsonl | tr -cd 'A-Za-z0-9_-')
fi
[ -n "$key" ] && key=-$key
# The session id names the mark: only the characters of a file name stay.
session=$(printf '%s' "$session" | tr -cd 'A-Za-z0-9_-')
[ -n "$session" ] && [ -f "$transcript" ] || exit 0

limit=${PLAN_RELAY_CONTEXT_LIMIT:-}
case $limit in ''|0*|*[!0-9]*) limit=150000 ;; esac
[ -n "$data" ] || data=${CLAUDE_PLUGIN_DATA:-${XDG_STATE_HOME:-$HOME/.local/state}/plan-relay}

# With jq, the usage is read by its key path (.message.usage), so the order of the keys and
# the objects nested inside it do not matter; a line cut by tail or not JSON is skipped.
# Without jq, the first } ends the usage, which holds while the three counters come before
# any nested object.
total=
if command -v jq >/dev/null 2>&1; then
  total=$(tail -n 400 "$transcript" | jq -R -r 'fromjson? | .message.usage? | select(type == "object")
    | (.input_tokens // 0) + (.cache_creation_input_tokens // 0) + (.cache_read_input_tokens // 0)' 2>/dev/null | tail -n 1)
fi
case $total in ''|*[!0-9]*)
  total=$(tail -n 400 "$transcript" | grep -o '"usage":{[^}]*}' | tail -1 | awk -F'[:,}]' '{
    s = 0
    for (i = 1; i < NF; i++) if ($i ~ /"(input_tokens|cache_creation_input_tokens|cache_read_input_tokens)"$/) s += $(i + 1)
    print s
  }') ;;
esac
[ -n "$total" ] || exit 0

near=$((limit * 9 / 10))
[ "$total" -ge "$near" ] || exit 0
if [ "$total" -lt "$limit" ]; then
  level=near
  warning=$(msg contextHook.near $((total / 1000)) $((limit / 1000)))
else
  level=over-$(((total - limit) / 50000))
  warning=$(msg contextHook.over $((total / 1000)) $((limit / 1000)))
fi
# the text goes in a JSON string: backslash and double quotes escaped
warning=$(printf '%s' "$warning" | sed -e 's/\\/\\\\/g' -e 's/"/\\"/g')

mkdir -p "$data" 2>/dev/null
mark="$data/context-$session$key-$level"
[ -e "$mark" ] && exit 0
: > "$mark"
# -mtime +6: age, in whole days, above 6, that is, 7 days or more.
find "$data" -type f -name 'context-*' -mtime +6 -exec rm -f {} + 2>/dev/null

printf '{"hookSpecificOutput":{"hookEventName":"PostToolUse","additionalContext":"%s"}}\n' "$warning"
